FUNCTION_BLOCK FB_S01
VAR_INPUT
    StartBtn : BOOL;
    LeftPartPresent : BOOL;
    RightPartPresent : BOOL;
    EStop_NC : BOOL;
END_VAR
VAR_OUTPUT
    ClampLeft : BOOL := FALSE;
    ClampRight : BOOL := FALSE;
    Busy : BOOL := FALSE;
    Status : WORD := WORD#16#0000;
END_VAR
VAR
    StartBtnLast : BOOL := FALSE;
    StartRise : BOOL := FALSE;
    StartupScans : USINT := 0;
    PendingLeft : BOOL := FALSE;
    PendingRight : BOOL := FALSE;
END_VAR

(*
需求原文：
双工位气动夹具用于同时定位两个零件，但气源只有一路，
因此两个夹具不能同时动作。

控制要求：
1. StartBtn 为上升沿触发：若左工位有零件
   （LeftPartPresent = TRUE）而右夹具未在夹紧，
   则左夹具 ClampLeft 夹紧；右侧对称。
2. 夹紧动作只做一次保持，不随 StartBtn 电平反复动作；
   要松开必须由同一按钮在另一工位动作时自动让位
   （即后启动的工位会等待）。
3. 任一工位没有零件（对应 PartPresent = FALSE）时，
   该侧不允许夹紧。
4. EStop_NC = FALSE（急停）时两侧夹具立即松开，
   ClampLeft 与 ClampRight 同时为 FALSE，并清空忙标志。
5. 任一时刻 ClampLeft 与 ClampRight 不得同时为 TRUE。
6. Busy 表示当前已有工位在夹紧过程中；
   Status 输出 16#0000 正常、16#8101 两侧同时请求、
   16#8102 急停中。

扫描周期：20 ms。

语义冲突及待审事项：
- 初态之外，C10 的 G[0,1] 还要求前两个扫描输出全为 FALSE，
  与需求1未限定启动时段的立即夹紧存在冲突。
  本实现优先满足 C10；此期间仅更新按钮历史，不缓存启动。
- 需求2的“要松开必须”与零件离位及急停强制松开冲突；
  本实现优先满足 C1、C2、C2b。
- 需求1禁止对侧夹紧时直接启动，需求2要求等待和自动让位。
  本实现将请求与夹紧分开：单侧请求使旧侧松开并保留请求，
  后一扫描在安全条件仍成立时夹紧新侧。
  原文未指定等待时长、夹紧完成反馈或气动释放时间；
  此扫描分离不代表气动机构已经完成释放，该时序需要审定。
- 两侧同时请求的仲裁、状态保持时长和 Busy 完成判据未定义。
  本实现不仲裁同时请求，保持已有合法夹紧；
  16#8101 表示当扫描的冲突上升沿，Busy 表示夹紧或等待请求。
上述解释仍需逐周期测试及需求审定；未声称编译或功能已验证。
*)

(* 每个扫描都更新边沿历史，包括急停和启动禁止期间。 *)
StartRise := StartBtn AND NOT StartBtnLast;
StartBtnLast := StartBtn;

Status := WORD#16#0000;

(* 零件离位立即解除该侧夹紧及其等待请求。 *)
IF NOT LeftPartPresent THEN
    ClampLeft := FALSE;
    PendingLeft := FALSE;
END_IF;

IF NOT RightPartPresent THEN
    ClampRight := FALSE;
    PendingRight := FALSE;
END_IF;

IF NOT EStop_NC THEN
    ClampLeft := FALSE;
    ClampRight := FALSE;
    PendingLeft := FALSE;
    PendingRight := FALSE;
    Busy := FALSE;
    Status := WORD#16#8102;

ELSIF StartupScans < 2 THEN
    ClampLeft := FALSE;
    ClampRight := FALSE;
    PendingLeft := FALSE;
    PendingRight := FALSE;
    Busy := FALSE;

    IF StartRise AND LeftPartPresent AND RightPartPresent THEN
        Status := WORD#16#8101;
    END_IF;

ELSE
    (* 异常互斥状态采取两侧释放，不暗中选择某一侧。 *)
    IF ClampLeft AND ClampRight THEN
        ClampLeft := FALSE;
        ClampRight := FALSE;
        PendingLeft := FALSE;
        PendingRight := FALSE;
        Status := WORD#16#8101;
    END_IF;

    IF PendingLeft AND PendingRight THEN
        PendingLeft := FALSE;
        PendingRight := FALSE;
        Status := WORD#16#8101;
    END_IF;

    (* 执行前一扫描留下的让位请求；输出与请求均受到位约束。 *)
    IF PendingLeft THEN
        IF LeftPartPresent AND NOT ClampRight THEN
            ClampLeft := TRUE;
            PendingLeft := FALSE;
        END_IF;
    ELSIF PendingRight THEN
        IF RightPartPresent AND NOT ClampLeft THEN
            ClampRight := TRUE;
            PendingRight := FALSE;
        END_IF;
    END_IF;

    IF StartRise THEN
        IF LeftPartPresent AND RightPartPresent THEN
            (* 无规定的优先工位：拒绝新增动作，保留合法保持。 *)
            Status := WORD#16#8101;

        ELSIF LeftPartPresent THEN
            PendingRight := FALSE;
            IF ClampRight THEN
                ClampRight := FALSE;
                PendingLeft := TRUE;
            ELSE
                ClampLeft := TRUE;
                PendingLeft := FALSE;
            END_IF;

        ELSIF RightPartPresent THEN
            PendingLeft := FALSE;
            IF ClampLeft THEN
                ClampLeft := FALSE;
                PendingRight := TRUE;
            ELSE
                ClampRight := TRUE;
                PendingRight := FALSE;
            END_IF;
        END_IF;
    END_IF;

    Busy := ClampLeft OR ClampRight OR PendingLeft OR PendingRight;
END_IF;

(* C10 以扫描索引 0、1 解释；急停不重新启动上电计数。 *)
IF StartupScans < 2 THEN
    StartupScans := StartupScans + 1;
END_IF;

END_FUNCTION_BLOCK
